 3	// [ai, aj[
 4	function sum(a: array<int>, i: int, j: int) : int
 5	  requires 0 <= i <= j <= a.Length
 6	  reads a
 7	  decreases j
 8	{
 9	  if i == j then 0
10	  else a[j-1] + sum(a, i, j-1)
11	}
12	
13	// 1 b)
14	method query(a: array<int>, i: int, j: int) returns (res : int)
15	  requires 0 <= i <= j <= (a.Length) + 1
16	  ensures res == sum(a, i, j)
17	{
18	  res := 0;
19	  var ind := j-1;
20	
21	  while ind >= i
22	    invariant i-1 <= ind < j
23	    invariant res == sum(a, i, j) - sum(a, i, ind+1)
24	    decreases ind
25	  {
26	    res := res + a[ind];
27	    ind := ind - 1;
28	  }
29	}
30	
31	// 1 c)
32	// a -> [1, 10, 3, −4, 5]
33	// c -> [0, 1, 11, 14, 10, 15]
34	method queryFast(a: array<int>, c: array<int>, i: int, j: int) returns (r: int)
35	  requires 0 <= i <= j <= a.Length
36	  requires is_prefix_sum_for(a,c)
37	  ensures r == sum(a, i, j)
38	{
39	  var k := i;
40	  proof(a, 0, j, k);
41	  r := c[j] - c[i];
42	}
43	
44	predicate is_prefix_sum_for (a: array<int>, c: array<int>)
45	  reads c, a
46	{
47	  a.Length + 1 == c.Length && forall i: int :: 0 <= i <= a.Length ==> c[i] == sum(a, 0, i)
48	}
49	
50	lemma proof(a: array<int>, i: int, j: int, k:int)
51	  requires 0 <= i <= k <= j <= a.Length
52	  ensures sum(a, i, k) + sum(a, k, j) == sum(a, i, j)
53	
