57	datatype List<T> = Nil | Cons(head: T, tail: List<T>)
58	
59	method from_array<T>(a: array<T>) returns (l: List<T>)
60	  ensures forall i: int :: 0 <= i < a.Length ==> mem(a[i], l)
61	  ensures forall x: T :: mem(x, l) ==> exists y: int :: 0 <= y < a.Length && a[y] == x
62	{
63	  l := Nil;
64	  var i := a.Length - 1;
65	  while i >= 0
66	    invariant 0 <= i+1 <= a.Length
67	    invariant forall j: int :: i < j < a.Length ==> mem(a[j], l)
68	    invariant forall x: T :: mem(x, l) ==> exists y: int :: i+1 <= y < a.Length && a[y] == x
69	    decreases i
70	  {
71	    l := Cons(a[i], l);
72	    i := i - 1;
73	  }
74	}
75	
76	function mem<T(==)> (x: T, l: List<T>) : bool
77	{
78	  match l
79	  case Nil => false
80	  case Cons(h, t) => h == x || mem(x, t)
81	}

